# Let me check what transformations might be happening in a more systematic way
# I'll look at what characters are being inserted vs. replaced

inputs = ['ahu', 'xaxz', 'bk', 'bdccy', 'ckiu']
outputs = ['hdhueb', 'xhdxz', 'kfdk', 'kfddccy', 'ckxaxxueb']

print("Looking for consistent replacement patterns:")
print()

# First, let's see what happens if we look at the transformations more systematically
# We'll track what characters get transformed to what

transformation_map = {}

for inp, outp in zip(inputs, outputs):
    print(f"'{inp}' -> '{outp}'")

    # Find all character mappings
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            if inp[i] not in transformation_map:
                transformation_map[inp[i]] = outp[i]
            else:
                if transformation_map[inp[i]] != outp[i]:
                    print(f"  Warning: Conflict! '{inp[i]}' maps to both '{transformation_map[inp[i]]}' and '{outp[i]}'")

    # Also check for additions (when output is longer)
    if len(outp) > len(inp):
        print(f"  Added characters at end: {outp[len(inp):]}")

print("\nCharacter transformation map:")
for k, v in transformation_map.items():
    print(f"  '{k}' -> '{v}'")

